constexpr s32 kTaskWork = 60;           // KwlnTask +0x3C: the work pointer
constexpr s32 kTaskChild = 80;          // KwlnTask +0x50: the first child (the controller's "collis sphere" task)

// the collision controller work (52 bytes)
constexpr s32 kCtlState = 0;            // 0 move pending, 1 idle, 2 off
constexpr s32 kCtlFlags = 4;
constexpr u32 kCtlFlagSnap = 0x40000000u;         // bit 30: land on the ground before moving
constexpr u32 kCtlFlagNoCollision = 0x10000000u;  // bit 28
constexpr u32 kCtlFlagFrozen = 0x08000000u;       // bit 27
constexpr s32 kCtlResId = 8;            // u16 scene resource id (type = id >> 10)
constexpr s32 kCtlUnitId = 10;          // u16 the field unit's id (unit +424)
constexpr s32 kCtlUnit = 12;            // the field unit whose model is the resource's
constexpr s32 kCtlModel = 16;
constexpr s32 kCtlMove = 20;            // f32[3] the pending displacement
constexpr s32 kCtlRadius = 32;          // f32
constexpr s32 kCtlWord36 = 36;
constexpr s32 kCtlDistance = 40;        // s32
constexpr s32 kCtlGridX = 44, kCtlGridZ = 48;

// scene resources (MT_Scene_GetRes / MT_Scene_GetResListHead)
constexpr s32 kResFlags = 40;           // bit 1: drawn / active
constexpr s32 kResNext = 248;
constexpr s32 kResModel = 296;          // the resource's model (type 1 / 3)
constexpr s32 kResBlockClump = 352;     // type 12 (Tartarus block): -> +8 the collision clump

// field units (448 bytes; fldhi:: in field_hi.h)
constexpr s32 kUnitInstance = 72, kUnitModel = 80, kUnitResource = 84, kUnitId = 424;

// the model matrix (sub_318B60 returns it): rows right +0, up +16, at +32, position +48
constexpr s32 kMtxAt = 32, kMtxPos = 48;

// sField (K_Field_Get) +4460: the field's collision record (+0 bit 0: an RW collision world at +12, else a clump at +8)
constexpr s32 kFieldCollision = 4460;
constexpr s32 kFieldGridCellRes = 76;   // sField + 72 + 256 z + 16 x + 4: the cell's u16 block resource id

// the sphere-contact record (see the file comment)
constexpr s32 kConNormal = 768, kConDist = 1536, kConFlag = 2560;
constexpr s32 kConGathering = 2816, kConCount = 2820, kConFlagged = 2824, kConStepDir = 2828;
constexpr s32 kConSphere = 2840, kConAtomic = 2868;

// the transparent-wall walk record (52 bytes, sub_1AD050 / sub_1AD220): +0 the result list ({+0 material count,
// +4 atomic count, +8 [64] materials, +264 [64] atomics}), +4 the line intersection, +48 the atomic being tested;
// the RW geometry fields read: +8 flags (0x40 = met by the walk), +32 the material table, +36 the material count,
// +44 the triangles (8 bytes, u16 material index at +6)
constexpr s32 kTwAtomic = 48;
constexpr s32 kGeoFlags = 8, kGeoMaterials = 32, kGeoMaterialCount = 36, kGeoTriangles = 44;

// the "collis mover" work (1,440 bytes)
constexpr s32 kMovFlags = 4, kMovRes = 12, kMovKind = 16, kMovMode = 24, kMovCount = 28, kMovQueue = 32;
constexpr s32 kMovState = 1204, kMovRwObject = 1228, kMovCount2 = 1240, kMovQueue2 = 1248;

// $gp words
constexpr s32 kGpFar = -32244;          // 0x7CAEFC: f32 FLT_MAX, the "no contact yet" distance
constexpr s32 kGpSceneIds = -22448;     // 0x7CD540: -> the scene record {s32 major, s32 minor, ..}

// the RW device's memory slots
constexpr s32 kRwFreeSlot = 380;        // 0x96017C RwFree
constexpr s32 kRwCallocSlot = 388;      // 0x960184 RwCalloc(count, size, hint)
